$mpcb$::jsonb) AS r(
    registration_no TEXT,
    name TEXT,
    address TEXT,
    district TEXT,
    facility_type TEXT,
    source_activity TEXT,
    source_document_date DATE,
    valid_until DATE,
    page_no INTEGER
  )
)
INSERT INTO public.facilities (
  name,
  address,
  district,
  facility_type,
  source_url,
  source_document_date,
  source_checked_on,
  authorization_valid_until,
  publication_status,
  source_registration_no,
  source_activity
)
SELECT
  r.name,
  r.address,
  r.district,
  r.facility_type,
  'https://www.ecmpcb.in/ewasteOutwardRegistry?page_no=' || r.page_no::TEXT,
  r.source_document_date,
  DATE '2026-11-16',
  r.valid_until,
  'candidate',
  r.registration_no,
  r.source_activity
FROM source_rows AS r
ON CONFLICT (source_registration_no, name) WHERE source_registration_no IS NOT NULL
DO NOTHING;
